1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	import java.time.LocalDate;
6	import java.time.temporal.ChronoUnit;
7	
8	/**
9	 * Derives an owner's numeric membership level (1 to 4) from the state captured
10	 * when the owner was created together with how long the owner has been
11	 * registered. Kept as a plain static helper - rather than a method on
12	 * {@link OwnerMapper} - so MapStruct does not mistake it for an implicit
13	 * property mapping.
14	 *
15	 * <p>The level starts at 1, gains 1 when an email address is present, gains a
16	 * further 1 when the name was unique on create ({@code namesakeCount} is 0), and
17	 * gains a final 1 when the owner's tenure exceeds {@link #TENURE_DAYS_FOR_LEVEL_4}
18	 * days. The result is capped at 4. Because a newly created owner has zero tenure,
19	 * a new owner never exceeds level 3.
20	 */
21	public final class MembershipLevel {
22	
23	    /** The lowest membership level, assigned to every owner. */
24	    private static final int BASE_LEVEL = 1;
25	
26	    /** The highest level assignable, reached only with sufficient tenure. */
27	    private static final int MAX_LEVEL = 4;
28	
29	    /** Tenure, in days, that must be exceeded to earn the level 4 bonus. */
30	    private static final int TENURE_DAYS_FOR_LEVEL_4 = 365;
31	
32	    private MembershipLevel() {
33	    }
34	
35	    /**
36	     * Computes the owner's membership level: 1, plus 1 when an email address is
37	     * present, plus 1 when {@code namesakeCount} is 0, plus 1 when the owner's
38	     * tenure exceeds {@link #TENURE_DAYS_FOR_LEVEL_4} days, capped at
39	     * {@link #MAX_LEVEL}.
40	     *
41	     * @param owner the owner whose level to derive
42	     * @return the numeric membership level between 1 and 4 inclusive
43	     */
44	    public static int forOwner(Owner owner) {
45	        int level = BASE_LEVEL;
46	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
47	            level++;
48	        }
49	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
50	            level++;
51	        }
52	        if (tenureExceedsLevel4Threshold(owner.getRegistrationDate())) {
53	            level++;
54	        }
55	        return Math.min(level, MAX_LEVEL);
56	    }
57	
58	    /**
59	     * Returns whether the tenure elapsed since {@code registrationDate} is more
60	     * than {@link #TENURE_DAYS_FOR_LEVEL_4} days. A {@code null} or future
61	     * registration date yields zero (or negative) tenure and therefore never
62	     * qualifies.
63	     *
64	     * @param registrationDate the day the owner was registered, or {@code null}
65	     * @return {@code true} when tenure exceeds the level 4 threshold
66	     */
67	    private static boolean tenureExceedsLevel4Threshold(LocalDate registrationDate) {
68	        if (registrationDate == null) {
69	            return false;
70	        }
71	        long tenureDays = ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
72	        return tenureDays > TENURE_DAYS_FOR_LEVEL_4;
73	    }
74	
75	}
